import ast

def find_lists(Input):
    """Return the number of list objects directly contained in the given tuple."""
    count = 0
    for element in Input:
        if isinstance(element, list):
            count += 1
    return count

if __name__ == "__main__":
    data = sys.stdin.read().strip()
    if not data:
        sys.exit()
    try:
        tpl = ast.literal_eval(data)
    except Exception:
        tpl = ()
    if not isinstance(tpl, tuple):
        tpl = ()
    print(find_lists(tpl))

