import sys
from functools import lru_cache

def get_max_sum(n):
    sys.setrecursionlimit(10**6)

    @lru_cache(maxsize=None)
    def f(x):
        if x <= 0:
            return 0
        total = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)
        return max(x, total)

    return f(n)

