import math

def _comb(N: int, K: int) -> int:
    """Compute binomial coefficient C(N, K) using an iterative multiplicative formula."""
    if K < 0 or K > N:
        return 0
    K = min(K, N - K)
    result = 1
    for i in range(1, K + 1):
        result = result * (N - K + i) // i
    return result

def count_binary_seq(n: int) -> int:
    """Return the number of binary sequences of length 2*n where the sum of the first n bits
    equals the sum of the last n bits.

    The count equals the central binomial coefficient C(2n, n).
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non‑negative")

    try:
        return math.comb(2 * n, n)
    except AttributeError:
        # Fallback for Python versions without math.comb
        return _comb(2 * n, n)

