def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def _to_float(x):
        """Convert int, float or numeric string (with '.' or ',') to a float."""
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str):
            # Standardize decimal separator and strip whitespace
            normalized = x.strip().replace(',', '.')
            try:
                return float(normalized)
            except ValueError:
                raise ValueError(f"String '{x}' does not represent a real number.")
        raise TypeError(f"Unsupported type: {type(x)}")

    val_a = _to_float(a)
    val_b = _to_float(b)

    if val_a == val_b:
        return None

    # Return the original argument that holds the larger numeric value
    return a if val_a > val_b else b

