def common_element(list1, list2):
    """Return True if the two lists share at least one common element."""
    # Try the fast path using a set (requires hashable elements)
    try:
        elements = set(list1)
        for item in list2:
            if item in elements:
                return True
        return False
    except TypeError:
        # Fallback for unhashable elements (e.g., lists, dicts)
        for a in list1:
            for b in list2:
                if a == b:
                    return True
        return False


