    print(common_element([1, 2, 3], [3, 4, 5]))   # True
    print(common_element(['a', 'b'], ['c', 'd'])) # False
    print(common_element(['a', 'b'], ['b', 'c'])) # True
    # Unhashable elements example
    print(common_element([[1], [2]], [[2], [3]])) # True
    print(common_element([[1], [2]], [[3], [4]])) # False

