import sys

sys.setrecursionlimit(10**6)


def get_max_sum(n):
    """Return the maximum sum defined by the recurrence:
       f(n) = max(f(n//2) + f(n//3) + f(n//4) + f(n//5), n)
    """
    memo = {0: 0}

    def resolve(x):
        if x in memo:
            return memo[x]
        # recursive splits
        total = (
            resolve(x // 2)
            + resolve(x // 3)
            + resolve(x // 4)
            + resolve(x // 5)
        )
        memo[x] = total if total > x else x
        return memo[x]

    return resolve(n)

