import math

def count_binary_seq(n):
    """Return the number of binary sequences of length 2n whose first n bits
    have the same sum as the last n bits.

    The answer equals the central binomial coefficient C(2n, n).

    Parameters:
        n (int): non‑negative length of each half.

    Returns:
        int: count of valid binary sequences.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non‑negative")
    # Use the built‑in comb if available (Python 3.8+)
    try:
        return math.comb(2 * n, n)
    except AttributeError:
        # Fallback for older Python versions: compute C(2n, n) manually
        result = 1
        for i in range(1, n + 1):
            result = result * (n + i) // i
        return result

