def common_element(list1, list2):
    """Return True if the two lists share at least one element."""
    try:
        # Fast path for hashable elements using set intersection
        return bool(set(list1) & set(list2))
    except TypeError:
        # Fallback for unhashable elements (e.g., lists, dicts)
        for a in list1:
            for b in list2:
                if a == b:
                    return True
        return False

