def is_sublist(l, s):
    """Return True if list `s` appears as a contiguous sublist in list `l`.

    An empty sublist is considered to be present in any list.
    """
    n, m = len(l), len(s)
    if m == 0:
        return True
    if m > n:
        return False
    for i in range(n - m + 1):
        if all(l[i + j] == s[j] for j in range(m)):
            return True
    return False

