from functools import lru_cache

def get_max_sum(n):
    """
    Compute the maximum sum defined by:
        f(n) = max( f(n//2) + f(n//3) + f(n//4) + f(n//5), n )
    using memoization for efficiency.
    """
    @lru_cache(maxsize=None)
    def f(x):
        if x == 0:
            return 0
        split_sum = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)
        return split_sum if split_sum > x else x

    return f(n)

