def common_element(list1, list2):
    """Return True if the two lists share at least one element."""
    if not list1 or not list2:
        return False
    # Use the smaller list to build a set for efficiency
    if len(list1) <= len(list2):
        seen = set(list1)
        for item in list2:
            if item in seen:
                return True
    else:
        seen = set(list2)
        for item in list1:
            if item in seen:
                return True
    return False

