from typing import List, Tuple

def _parse_time(t: str) -> int:
    """Convert a \"HH:MM\" time string to minutes since midnight."""
    parts = t.split(":")
    if len(parts) != 2:
        raise ValueError(f"Invalid time format: {t}")
    hour, minute = parts
    return int(hour) * 60 + int(minute)

def _format_time(m: int) -> str:
    """Convert minutes since midnight back to a zero‑padded \"HH:MM\" string."""
    hour = m // 60
    minute = m % 60
    return f"{hour:02d}:{minute:02d}"

def merge_shifts(shifts: List[Tuple[str, str]]) -> List[Tuple[str, str]]:
    """Each shift is a (start, end) tuple of \"HH:MM\" strings within one day, with end after start.
    Merge shifts that overlap or touch. Drop merged shifts shorter than 15 minutes.
    Return the merged shifts as (start, end) tuples sorted by start.

    merge_shifts([("09:00", "12:00"), ("11:30", "13:00")]) == [("09:00", "13:00")]
    """
    # Convert input shifts to (start_minute, end_minute) tuples.
    intervals = [(_parse_time(start), _parse_time(end)) for start, end in shifts]

    # Sort intervals by start time.
    intervals.sort(key=lambda x: x[0])

    merged: List[List[int]] = []
    for start, end in intervals:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            # Overlap or touch when the current start is <= the previous end.
            if start <= last_end:
                # Extend the previous interval if needed.
                if end > last_end:
                    merged[-1][1] = end
            else:
                merged.append([start, end])

    # Filter out intervals shorter than 15 minutes.
    result: List[Tuple[str, str]] = []
    for start, end in merged:
        if end - start >= 15:
            result.append((_format_time(start), _format_time(end)))

    return result

